const report = $input.first().json;
const config = $('Configuração').first().json;
if (!report.pdf?.base64 || !report.html) throw new Error('Relatório incompleto; envio interrompido.');
if (!config.testMode && report.kind === 'overdue' && report.equipmentCount === 0) return [];
return [{json: {...config, ...report, pdf: undefined}, binary: {report: {data: report.pdf.base64, mimeType: 'application/pdf', fileName: report.pdf.filename, fileExtension: 'pdf'}}}];

const item = $input.first();
const config = $('Configuração').first().json;
const report = item.json;
if (config.testMode !== true && config.testMode !== false) throw new Error('testMode deve ser booleano.');
const destinations = config.testMode ? [config.testEmail] : report.recipients?.emails;
if (!Array.isArray(destinations)) throw new Error('Destinatários não fornecidos pela API. Atualize o sistema.');
return [...new Set(destinations.filter(v=>typeof v === 'string' && v.trim()).map(v=>v.trim()))].map(destination=>({json:{...report,destination},binary:item.binary}));

